// static
bool StructTraits<::arc::mojom::Buffer::DataView, ::arc::mojom::BufferPtr>::Read(
    ::arc::mojom::Buffer::DataView input,
    ::arc::mojom::BufferPtr* output) {
  bool success = true;
  ::arc::mojom::BufferPtr result(::arc::mojom::Buffer::New());
  
      if (success)
        result->timestamp = input.timestamp();
      if (success)
        result->handle_fd = input.TakeHandleFd();
      if (success)
        result->size = input.size();
      if (success)
        result->offset = input.offset();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::arc::mojom::VideoDecoderConfig::DataView, ::arc::mojom::VideoDecoderConfigPtr>::Read(
    ::arc::mojom::VideoDecoderConfig::DataView input,
    ::arc::mojom::VideoDecoderConfigPtr* output) {
  bool success = true;
  ::arc::mojom::VideoDecoderConfigPtr result(::arc::mojom::VideoDecoderConfig::New());
  
      if (success && !input.ReadProfile(&result->profile))
        success = false;
      if (success && !input.ReadCodedSize(&result->coded_size))
        success = false;
  *output = std::move(result);
  return success;
}

// static
bool UnionTraits<::arc::mojom::DecoderBuffer::DataView, ::arc::mojom::DecoderBufferPtr>::Read(
    ::arc::mojom::DecoderBuffer::DataView input,
    ::arc::mojom::DecoderBufferPtr* output) {
  using UnionType = ::arc::mojom::DecoderBuffer;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::BUFFER: {
      ::arc::mojom::BufferPtr result_buffer;
      if (!input.ReadBuffer(&result_buffer))
        return false;

      *output = UnionType::NewBuffer(
          std::move(result_buffer));
      break;
    }
    case Tag::END_OF_STREAM: {
      *output = UnionType::NewEndOfStream(input.end_of_stream());
      break;
    }
    default:

      return false;
  }
  return true;
}

