void VideoDecoderAsyncWaiter::Initialize(
    VideoDecoderConfigPtr config, ::mojo::PendingRemote<VideoDecoderClient> client, ::mojo::PendingAssociatedReceiver<::arc::mojom::VideoFramePool> video_frame_pool, DecoderStatus* out_status) {
  base::RunLoop loop;
  proxy_->Initialize(std::move(config),std::move(client),std::move(video_frame_pool),
      base::BindOnce(
          [](base::RunLoop* loop,
             DecoderStatus* out_status
,
             DecoderStatus status) {*out_status = std::move(status);
            loop->Quit();
          },
          &loop,
          out_status));
  loop.Run();
}
void VideoDecoderAsyncWaiter::Decode(
    DecoderBufferPtr buffer, DecoderStatus* out_status) {
  base::RunLoop loop;
  proxy_->Decode(std::move(buffer),
      base::BindOnce(
          [](base::RunLoop* loop,
             DecoderStatus* out_status
,
             DecoderStatus status) {*out_status = std::move(status);
            loop->Quit();
          },
          &loop,
          out_status));
  loop.Run();
}
